function toMillis(t) {
  if (/^\d{2}:\d{2}$/.test(t)) {
    const [h, m] = t.split(":").map(Number);
    const d = new Date();
    d.setHours(h, m, 0, 0);
    return d.getTime();
  }
  return Date.parse(t) || Date.now();
}

let data = msg.payload;

// 🧩 ถ้า MQTT ส่งมาทีละค่า เช่น {time:"...", heartRate:"80"}
if (data && data.heartRate !== undefined) {
  // แปลง heartRate ให้เป็นตัวเลขเสมอ
  data.heartRate = Number(data.heartRate);
  let logs = flow.get("heartLogs") || [];
  logs.push(data);
  if (logs.length > 10) logs.shift();
  flow.set("heartLogs", logs);
  data = { heartrate: logs };
}

// ❗ ถ้าไม่มี array heartrate
if (!data || !Array.isArray(data.heartrate)) {
  node.warn("ไม่มีข้อมูล heartrate");
  return null;
}

// ✅ ล้างกราฟก่อน
let clearMsg = { ui_control: { clear: true } };

// ✅ จุดล่าสุด
let last = data.heartrate[data.heartrate.length - 1];
let chartMsg = {
  topic: "BPM",
  payload: {
    x: toMillis(last.time),
    y: Number(last.heartRate),
  },
};

// ✅ คำนวณ avg/min/max ให้แน่ใจว่าเป็นตัวเลข
const hrValues = data.heartrate.map(p => Number(p.heartRate)).filter(v => !isNaN(v));

let avg = 0, minVal = 0, maxVal = 0;
if (hrValues.length > 0) {
  avg = hrValues.reduce((a, b) => a + b, 0) / hrValues.length;
  minVal = Math.min(...hrValues);
  maxVal = Math.max(...hrValues);
}

// ✅ ส่งออก 2 ทาง
return [
  [clearMsg, chartMsg],
  { payload: { avg, minVal, maxVal, heartrate: data.heartrate } },
];

const now = new Date();
const d = String(now.getDate()).padStart(2, "0");
const m = String(now.getMonth() + 1).padStart(2, "0");
const y = String(now.getFullYear());
const today = `${d}-${m}-${y}`;

const data = msg.payload;

if (data && Array.isArray(data.log)) {
    const convertYear = (year) => (year > 2500 ? year - 543 : year);

    const todayLogs = data.log.filter(l => {
        if (!l.date) return false;
        const [day, month, year] = l.date.split('-').map(Number);
        const gregorianYear = convertYear(year);

        const logDateStr = `${String(day).padStart(2, '0')}-${String(month).padStart(2, '0')}-${gregorianYear}`;
        return logDateStr === today;
    });

    msg.payload = { log: todayLogs };
} else {
    msg.payload = { log: [] };
}

return msg;

// 🟢 ข้อมูลเข้า msg.payload = user object
let user = msg.payload;

// ถ้าไม่มี log ให้หยุด
if (!user || !Array.isArray(user.log)) {
  node.warn("ไม่มีข้อมูล log");
  return [null]; // ✅ ต้อง return array เสมอ
}

// 🧩 แปลง log เป็น format ที่ UI ใช้
const history = user.log.map(item => ({
  date: item.date,
  time: item.time,
  slot: "Slot " + item.slot,
  name: item.list,
  status: item.take ? "Taken" : "Missed"
}));

// 🧮 นับจำนวนแต่ละสถานะ
const takenCount = history.filter(h => h.status === "Taken").length;
const missedCount = history.filter(h => h.status === "Missed").length;

// ถ้ามีข้อมูลใน schedule ที่ยังไม่เกิดขึ้น → Pending
const scheduleCount = Array.isArray(user.schedule) ? user.schedule.length : 0;
const pendingCount = Math.max(scheduleCount - (takenCount + missedCount), 0);

// 💯 รวมเป็นเปอร์เซ็นต์
const total = takenCount + missedCount + pendingCount || 1;
const toPercent = v => Math.round((v / total) * 100);

const stats = {
  taken: toPercent(takenCount),
  missed: toPercent(missedCount),
  pending: toPercent(pendingCount)
};

// 🟢 รวมออกเป็น payload ที่ UI ต้องใช้
msg.payload = {
  history,
  stats
};

// ✅ ต้อง return [msg] ไม่ใช่ msg เดี่ยว ๆ
return [msg];

// ถ้า payload เป็น string ของตัวเลข เช่น "85" → แปลงเป็น number
if (typeof msg.payload === "string") {
    msg.payload = parseFloat(msg.payload);
}

// ถ้า payload เป็น object มี heartRate อยู่แล้ว
if (typeof msg.payload === "object" && msg.payload.heartRate !== undefined) {
    let data = msg.payload;
    let heartRate = parseFloat(data.heartRate);
    let time = data.time || new Date().toLocaleString();
    msg.payload = { time, heartRate };
}

// ถ้า payload เป็นตัวเลขดิบ เช่น 0, 85, 120
else if (typeof msg.payload === "number") {
    let heartRate = msg.payload;
    let time = new Date().toLocaleString();
    msg.payload = { time, heartRate };
}

// ✅ เก็บค่าใน flow memory
let logs = flow.get("heartLogs") || [];
logs.push(msg.payload);

// จำกัดข้อมูลแค่ 20 ค่า (กัน chart ล้น)
if (logs.length > 20) logs.shift();

flow.set("heartLogs", logs);

node.status({
  fill: "green",
  shape: "dot",
  text: `HR:${msg.payload.heartRate} @ ${msg.payload.time}`
});

msg.payload = { heartrate: logs }; // ✅ ส่งออกให้ node ถัดไป
return msg;

// 🟢 ใช้ชื่อ collection ที่ถูกต้อง
msg.collection = "myCollection";  // ✅ ชื่อ collection ต้องตรงกับใน MongoDB

// 🟡 Operation: updateOne
msg.operation = "updateOne";

// 🧩 ดึงข้อมูล profile จาก UI payload
const profile = msg.payload.profile;

// if (!profile || !profile.email) {
//     node.warn("⚠️ ไม่มีข้อมูล profile หรือไม่มี email");
//     return null;
