// 🎯 Filter: ใช้ email เป็น key ในการหา document
const filter = { id: "1" };

// 🧱 ข้อมูลที่จะอัปเดต
const update = {
    $set: {
        name: profile.name,
        phone: profile.phone,
        email: profile.email,
        // phone: profile.phone,
        address: profile.address,
        avatar: profile.avatar
    }
};

// 📦 รวมทั้งหมดเข้า msg.payload
msg.payload = [filter, update];

